using Fgs.Foundation.Paging;
namespace Fgs.Asset.Infrastructure.AssetAttributeValues;
internal static class FgsAssetAttributeValueSql { public const string Table = "asset.\"FgsAssetAttributeValue\""; public const string SelectDetailColumns = "\"Id\", \"AssetId\", \"AssetAttributeId\", \"OptionId\", \"ValueText\", \"ValueInteger\", \"ValueDecimal\", \"ValueDate\", \"ValueBoolean\""; public const string SelectSummaryColumns = SelectDetailColumns; public const string SelectLookupColumns = SelectDetailColumns; private static readonly HashSet<string> AllowedSortColumns = new(StringComparer.OrdinalIgnoreCase) { "Id", "AssetId", "AssetAttributeId" }; public static string ResolveOrderBy(string? sortBy, SortDirection direction) { var dir = direction == SortDirection.Desc ? "DESC" : "ASC"; if (string.IsNullOrWhiteSpace(sortBy) || !AllowedSortColumns.Contains(sortBy)) return $"ORDER BY \"Id\" {dir}"; return $"ORDER BY \"{AllowedSortColumns.First(c => c.Equals(sortBy, StringComparison.OrdinalIgnoreCase))}\" {dir}"; } }
